#!/usr/bin/env node
// Build the Agent Undercover demo video from one raw screen recording.
//
// Input: an edit-decision JSON (see scripts/video/README.md) that maps source
// timestamps to final-video segments, subtitles, and narration lines.
// Output: 1920x1080 / 30fps / H.264 MP4 with burned-in subtitles and an
// AI English voiceover generated by edge-tts.
//
// Subtitles and the end card are rendered as transparent PNGs with Pillow and
// overlaid by ffmpeg, so the ffmpeg build does not need libass/freetype.
//
// Usage:
//   node scripts/video/build-demo-video.mjs recordings/edit.json
//   node scripts/video/build-demo-video.mjs recordings/edit.json --dry-run
//   node scripts/video/build-demo-video.mjs recordings/edit.json --tts-only

import { spawnSync } from "node:child_process";
import { createHash } from "node:crypto";
import {
  existsSync,
  mkdirSync,
  readFileSync,
  writeFileSync,
} from "node:fs";
import { createRequire } from "node:module";
import { dirname, resolve } from "node:path";

const ROOT = resolve(import.meta.dirname, "../..");
const TTS_BIN = resolve(ROOT, ".video-tools/bin/edge-tts");
const PYTHON_BIN = resolve(ROOT, ".video-tools/bin/python");
const GRAPHICS_SCRIPT = resolve(ROOT, "scripts/video/render_graphics.py");

const videoToolsRequire = createRequire(resolve(ROOT, ".video-tools/package.json"));
function localBinary(pkg) {
  try {
    const resolved = videoToolsRequire(pkg);
    return typeof resolved === "string" ? resolved : resolved.path;
  } catch {
    return undefined;
  }
}
const FFMPEG = process.env.FFMPEG_PATH ?? localBinary("@ffmpeg-installer/ffmpeg") ?? "ffmpeg";
const FFPROBE = process.env.FFPROBE_PATH ?? localBinary("@ffprobe-installer/ffprobe") ?? "ffprobe";
// macOS defaults; override on other platforms with FONT_REGULAR/FONT_BOLD.
const FONT_REGULAR = process.env.FONT_REGULAR ?? "/System/Library/Fonts/Supplemental/Arial.ttf";
const FONT_BOLD = process.env.FONT_BOLD ?? "/System/Library/Fonts/Supplemental/Arial Bold.ttf";

const [editPathArg, ...flags] = process.argv.slice(2);
if (!editPathArg) {
  console.error("usage: node scripts/video/build-demo-video.mjs <edit.json> [--dry-run]");
  process.exit(1);
}
const dryRun = flags.includes("--dry-run");
const ttsOnly = flags.includes("--tts-only");
const editPath = resolve(ROOT, editPathArg);
const edit = JSON.parse(readFileSync(editPath, "utf8"));
const workDir = dirname(editPath);
const source = resolve(ROOT, edit.source);
const output = resolve(ROOT, edit.output);
const W = edit.width ?? 1920;
const H = edit.height ?? 1080;
const FPS = edit.fps ?? 30;
const voice = edit.voice ?? "en-US-AndrewNeural";
const voiceRate = edit.voiceRate ?? "-4%";
const segments = edit.segments ?? [];
const endCard = edit.endCard ?? {};
const sourceCrop = edit.sourceCrop;

if (!existsSync(source)) fail(`source video not found: ${source}`);
if (
  sourceCrop &&
  !(sourceCrop.width > 0 && sourceCrop.height > 0 && sourceCrop.x >= 0 && sourceCrop.y >= 0)
) {
  fail("sourceCrop must be { x, y, width, height } with non-negative x/y and positive size");
}
if (!segments.length) fail("edit.segments is empty");
if (!existsSync(TTS_BIN)) fail(`edge-tts not found at ${TTS_BIN} — create .video-tools first`);
if (!existsSync(PYTHON_BIN)) fail(`python not found at ${PYTHON_BIN} — create .video-tools first`);
if (!existsSync(GRAPHICS_SCRIPT)) fail(`graphics renderer not found at ${GRAPHICS_SCRIPT}`);
if (!existsSync(FONT_BOLD) || !existsSync(FONT_REGULAR)) {
  fail(`fonts not found: ${FONT_REGULAR}, ${FONT_BOLD} — set FONT_REGULAR/FONT_BOLD`);
}

// ---- timeline -------------------------------------------------------------

let cursor = 0;
for (const [i, seg] of segments.entries()) {
  seg.speed = seg.speed ?? 1;
  if (!(seg.end > seg.start)) fail(`segment ${i}: end must be > start`);
  if (!(seg.speed > 0)) fail(`segment ${i}: speed must be > 0`);
  seg.duration = (seg.end - seg.start) / seg.speed;
  seg.outStart = cursor;
  seg.outEnd = cursor + seg.duration;
  cursor = seg.outEnd;
}
const videoDuration = cursor;
const endCardDuration = endCard.duration ?? 4;
const totalDuration = videoDuration + endCardDuration;

// ---- narration ------------------------------------------------------------

mkdirSync(resolve(workDir, "voice"), { recursive: true });
const narrations = [];
for (const [i, seg] of segments.entries()) {
  if (!seg.narration) continue;
  const text = String(seg.narration).trim();
  const hash = createHash("sha1").update(`${voice}|${voiceRate}|${text}`).digest("hex").slice(0, 12);
  const file = resolve(workDir, "voice", `${hash}.mp3`);
  if (!existsSync(file)) {
    if (dryRun) {
      console.log(`[tts] would generate ${file}`);
    } else {
      console.log(`[tts] ${text.slice(0, 60)}${text.length > 60 ? "…" : ""}`);
      run(TTS_BIN, [
        "--voice", voice,
        `--rate=${voiceRate}`,
        "--text", text,
        "--write-media", file,
      ]);
    }
  }
  const startAbs = seg.narrationAt ?? seg.outStart + (seg.narrationDelay ?? 0.25);
  narrations.push({ index: i, text, file, startAbs, duration: existsSync(file) ? probeDuration(file) : 0 });
}

if (endCard.narration) {
  const text = String(endCard.narration).trim();
  const hash = createHash("sha1").update(`${voice}|${voiceRate}|${text}`).digest("hex").slice(0, 12);
  const file = resolve(workDir, "voice", `${hash}.mp3`);
  if (!existsSync(file)) {
    if (dryRun) {
      console.log(`[tts] would generate ${file}`);
    } else {
      console.log(`[tts] ${text.slice(0, 60)}${text.length > 60 ? "…" : ""}`);
      run(TTS_BIN, [
        "--voice", voice,
        `--rate=${voiceRate}`,
        "--text", text,
        "--write-media", file,
      ]);
    }
  }
  const startAbs = endCard.narrationAt ?? videoDuration + (endCard.narrationDelay ?? 0.3);
  narrations.push({ index: segments.length, text, file, startAbs, duration: existsSync(file) ? probeDuration(file) : 0 });
}

for (const [i, n] of narrations.entries()) {
  const prev = narrations[i - 1];
  if (prev && n.startAbs < prev.startAbs + prev.duration) {
    console.warn(
      `[warn] narration overlaps at ${fmt(n.startAbs)}s: "${n.text.slice(0, 40)}…" starts before previous ends (${fmt(prev.startAbs + prev.duration)}s)`,
    );
  }
  if (n.startAbs + n.duration > totalDuration) {
    console.warn(`[warn] narration runs past the end of the video (${fmt(n.startAbs + n.duration)}s > ${fmt(totalDuration)}s)`);
  }
}
if (ttsOnly) {
  for (const [i, n] of narrations.entries()) {
    console.log(`[tts ${i + 1}] ${fmt(n.startAbs)} + ${fmt(n.duration)}  ${n.text}`);
  }
  process.exit(0);
}

// ---- subtitles + end card (Pillow -> PNG) ---------------------------------

const graphicsDir = resolve(workDir, "graphics");
mkdirSync(graphicsDir, { recursive: true });
const subtitleGraphics = [];
for (const seg of segments) {
  if (!seg.subtitle) continue;
  const start = seg.outStart + 0.15;
  const end = seg.outEnd - 0.15;
  if (end <= start) continue;
  const out = resolve(graphicsDir, `sub-${String(subtitleGraphics.length).padStart(2, "0")}.png`);
  subtitleGraphics.push({ text: seg.subtitle, out, start, end });
}
const endCardPng = resolve(graphicsDir, "endcard.png");
const graphicsSpecPath = resolve(graphicsDir, "spec.json");
writeFileSync(
  graphicsSpecPath,
  JSON.stringify(
    {
      width: W,
      height: H,
      fontRegular: FONT_REGULAR,
      fontBold: FONT_BOLD,
      subtitles: subtitleGraphics.map(({ text, out }) => ({ text, out })),
      endCard: {
        out: endCardPng,
        title: endCard.title ?? "Agent Undercover",
        subtitle: endCard.subtitle ?? "Five players. One is lying.",
        lines: endCard.lines ?? [],
      },
    },
    null,
    2,
  ),
);
run(PYTHON_BIN, [GRAPHICS_SCRIPT, graphicsSpecPath]);
console.log(`[graphics] ${subtitleGraphics.length} subtitle cards + end card`);

// ---- ffmpeg filter graph --------------------------------------------------

const parts = [];
for (const [i, seg] of segments.entries()) {
  let vf = `trim=start=${seg.start}:end=${seg.end},setpts=(PTS-STARTPTS)/${seg.speed ?? 1}`;
  if (sourceCrop) {
    vf += `,crop=${sourceCrop.width}:${sourceCrop.height}:${sourceCrop.x}:${sourceCrop.y}`;
  }
  vf += `,scale=${W}:${H}:force_original_aspect_ratio=decrease`;
  vf += `,pad=${W}:${H}:(ow-iw)/2:(oh-ih)/2:color=black`;
  const zoom = seg.zoom ?? 1;
  if (zoom !== 1) {
    // Zoom by scaling up, then crop a W×H window. `focus` (normalized 0–1)
    // picks the point the window centers on; default is the frame center.
    const zoomW = Math.trunc((W * zoom) / 2) * 2;
    const zoomH = Math.trunc((H * zoom) / 2) * 2;
    const focusX = Math.min(Math.max(seg.focus?.x ?? 0.5, 0), 1);
    const focusY = Math.min(Math.max(seg.focus?.y ?? 0.5, 0), 1);
    const cropX = Math.round(
      Math.min(Math.max(focusX * zoomW - W / 2, 0), zoomW - W),
    );
    const cropY = Math.round(
      Math.min(Math.max(focusY * zoomH - H / 2, 0), zoomH - H),
    );
    vf += `,scale=${zoomW}:${zoomH}:flags=lanczos,crop=${W}:${H}:${cropX}:${cropY}`;
  }
  vf += ",format=yuv420p,setsar=1";
  parts.push(`[0:v]${vf}[v${i}]`);
}
parts.push(`${segments.map((_, i) => `[v${i}]`).join("")}concat=n=${segments.length}:v=1:a=0[vc]`);
parts.push(`color=c=0x0B1020:s=${W}x${H}:r=${FPS}:d=${endCardDuration}[ec]`);
parts.push(`[ec]format=yuv420p,setsar=1[ecv]`);
parts.push(`[vc][ecv]concat=n=2:v=1:a=0[vcraw]`);
// Apply fps once, after concat. On this ffmpeg build, fps after a trim is
// anchored to the source's absolute PTS, padding every cut back to its full
// source timestamp and pushing later cuts out of the output.
parts.push(`[vcraw]fps=${FPS},format=yuv420p,setsar=1[vc2]`);

let vlabel = "vc2";
subtitleGraphics.forEach((g, i) => {
  parts.push(`[${i + 1}:v]format=rgba[s${i}]`);
  parts.push(
    `[${vlabel}][s${i}]overlay=0:0:enable='between(t,${g.start.toFixed(3)},${g.end.toFixed(3)})'[vs${i}]`,
  );
  vlabel = `vs${i}`;
});
const endCardInput = 1 + subtitleGraphics.length;
parts.push(`[${endCardInput}:v]format=rgba[ecimg]`);
parts.push(
  `[${vlabel}][ecimg]overlay=0:0:enable='between(t,${videoDuration.toFixed(3)},${totalDuration.toFixed(3)})'[vend]`,
);
parts.push(
  `[vend]fade=t=in:st=0:d=0.4,fade=t=out:st=${(totalDuration - 0.6).toFixed(3)}:d=0.6[v]`,
);

const inputs = ["-i", source];
for (const g of subtitleGraphics) inputs.push("-i", g.out);
inputs.push("-i", endCardPng);
const narrationInputBase = endCardInput + 1;

const audioParts = [];
for (const [i, n] of narrations.entries()) {
  inputs.push("-i", n.file);
  const delayMs = Math.round(n.startAbs * 1000);
  const totalSamples = Math.ceil(totalDuration * 48000);
  audioParts.push(
    `[${narrationInputBase + i}:a]aformat=sample_rates=48000:channel_layouts=stereo,adelay=${delayMs}|${delayMs},apad=whole_len=${totalSamples}[a${i}]`,
  );
}
if (narrations.length) {
  // This ffmpeg build predates amix's normalize=0, so compensate for its
  // 1/N scaling explicitly after mixing padded inputs.
  audioParts.push(
    `${narrations.map((_, i) => `[a${i}]`).join("")}amix=inputs=${narrations.length}:duration=longest:dropout_transition=0,volume=${narrations.length},atrim=0:${totalDuration},asetpts=PTS-STARTPTS,loudnorm=I=-16:TP=-1.5:LRA=11,aresample=48000[a]`,
  );
} else {
  audioParts.push(`anullsrc=r=48000:cl=stereo,atrim=0:${totalDuration}[a]`);
}

const filterGraph = [...parts, ...audioParts].join(";");

console.log(`[timeline] ${segments.length} cuts, ${totalDuration.toFixed(2)}s total, ${narrations.length} narration lines`);
for (const seg of segments) {
  console.log(
    `  ${fmt(seg.outStart)}–${fmt(seg.outEnd)}  src ${fmt(seg.start)}–${fmt(seg.end)}  x${seg.speed ?? 1}${(seg.zoom ?? 1) !== 1 ? ` zoom ${seg.zoom}` : ""}${seg.subtitle ? `  “${seg.subtitle}”` : ""}`,
  );
}
console.log(`  ${fmt(videoDuration)}–${fmt(totalDuration)}  end card`);

if (dryRun) {
  console.log("[dry-run] no encode performed");
  process.exit(0);
}

mkdirSync(dirname(output), { recursive: true });
const args = [
  "-y",
  ...inputs,
  "-filter_complex", filterGraph,
  "-map", "[v]",
  "-map", "[a]",
  "-t", totalDuration.toFixed(3),
  "-c:v", "libx264",
  "-preset", "slow",
  "-crf", "20",
  "-pix_fmt", "yuv420p",
  "-r", String(FPS),
  "-c:a", "aac",
  "-b:a", "192k",
  "-movflags", "+faststart",
  output,
];
console.log(`[ffmpeg] encoding ${output}`);
const ffmpeg = spawnSync(FFMPEG, args, { stdio: "inherit" });
if (ffmpeg.status !== 0) fail("ffmpeg failed");
console.log(`[done] ${output}`);

// ---- helpers --------------------------------------------------------------

function probeDuration(file) {
  const r = spawnSync(FFPROBE, [
    "-v", "error",
    "-show_entries", "format=duration",
    "-of", "default=nw=1:nk=1",
    file,
  ], { encoding: "utf8" });
  if (r.status !== 0) fail(`ffprobe failed for ${file}: ${r.stderr}`);
  return Number.parseFloat(r.stdout.trim());
}

function run(cmd, args) {
  const r = spawnSync(cmd, args, { stdio: "inherit" });
  if (r.status !== 0) fail(`${cmd} failed with exit ${r.status}`);
}

function fmt(t) {
  return `${Number(t).toFixed(2)}s`;
}

function fail(msg) {
  console.error(`[error] ${msg}`);
  process.exit(1);
}
